fn choose_odd(v: &Vec<u64>) -> usize {
    // Find the position of the first odd element and return it.
    // We know there is at least one odd element, so `unwrap` is safe.
    v.iter()
     .position(|&x| x & 1 == 1)
     .unwrap()
}

